package textbounds

import (
	"fmt"

	"github.com/margince/margince/backend/internal/shared/kernel/values"
)

func Frontend() string {
	return fmt.Sprintf(`// SPDX-License-Identifier: BUSL-1.1
// SPDX-FileCopyrightText: 2026 Gradion
// Code generated by gen-textbounds. DO NOT EDIT.

export const TEXT_LIMITS = Object.freeze({
  label: %d,
  line: %d,
  note: %d,
  document: %d,
});
`, values.TextLabelCharacters, values.TextLineCharacters, values.TextNoteCharacters, values.TextDocumentCharacters)
}
